	First  T      `json:"first"`
	Second U      `json:"second,omitempty"`
	name   string `db:"name" xml:"nm"`
}

type Shape interface {
	Area() float64
	Perimeter() float64
}

type Reader interface {
	Read(p []byte) (n int, err error)
}

const Pi = 3.14159

const (
	A = iota
	B
)

var Global = "global value"

var (
	x int    = 1
	y string = "why"
)

func init() {
	fmt.Println("init")
}

func free(a int, b string) (int, error) {
	return a + len(b), nil
}

func Generic[T any](v T) T {
	return v
}

func (p Pair[T, U]) Swap() (U, T) {
	return p.Second, p.First
}

func (p *Pair[T, U]) Set(f T) {
	p.First = f
}

func main() {
	defer fmt.Println("deferred")
	defer func() {
		recover()
	}()

	go free(1, "two")
	go func() {
		fmt.Println("goroutine")
	}()

	ch := make(chan int)
	select {
	case v := <-ch:
		fmt.Println(v)
	default:
		fmt.Println("nothing")
	}

	switch n := 3; n {
	case 1:
		fmt.Println("one")
	default:
		fmt.Println("other")
	}

	var i interface{} = 5
	switch i.(type) {
	case int:
		fmt.Println("int")
	}

Loop:
	for i := 0; i < 3; i++ {
		if i == 1 {
			goto End
		}
		continue Loop
	}

End:
	s := `raw string
with newline`
	t := "interpreted \"str\""
	_ = s + t + str.ToUpper("x") + os.Getenv("HOME")
}
EOF
